create extension if not exists pgcrypto;
create table public.draft_allowed_users(user_id uuid primary key references auth.users(id) on delete cascade,created_at timestamptz not null default now());alter table public.draft_allowed_users enable row level security;create policy "user reads own allowlist" on public.draft_allowed_users for select to authenticated using(user_id=auth.uid());
create table public.leagues(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id),name text not null,slug text not null,created_at timestamptz not null default now(),unique(owner_id,slug));
create table public.seasons(id uuid primary key default gen_random_uuid(),league_id uuid not null references public.leagues(id) on delete cascade,year integer not null check(year between 2000 and 2200),name text not null,created_at timestamptz not null default now(),unique(league_id,year));
create table public.league_settings(id uuid primary key default gen_random_uuid(),season_id uuid not null unique references public.seasons(id) on delete cascade,scoring_label text not null,ppr numeric not null,idp_enabled boolean not null default false);
create table public.managers(id uuid primary key default gen_random_uuid(),league_id uuid not null references public.leagues(id) on delete cascade,display_name text not null,active boolean not null default true);
create table public.season_teams(id uuid primary key default gen_random_uuid(),season_id uuid not null references public.seasons(id) on delete cascade,manager_id uuid not null references public.managers(id),active boolean not null default true,unique(season_id,manager_id));
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['leagues','seasons','league_settings','managers','season_teams'] LOOP EXECUTE format('alter table public.%I enable row level security',t);END LOOP;END$$;
create policy "owner leagues" on public.leagues for all to authenticated using(owner_id=auth.uid() and exists(select 1 from public.draft_allowed_users a where a.user_id=auth.uid())) with check(owner_id=auth.uid() and exists(select 1 from public.draft_allowed_users a where a.user_id=auth.uid()));
create policy "owner seasons" on public.seasons for all to authenticated using(exists(select 1 from public.leagues l join public.draft_allowed_users a on a.user_id=auth.uid() where l.id=league_id and l.owner_id=auth.uid())) with check(exists(select 1 from public.leagues l join public.draft_allowed_users a on a.user_id=auth.uid() where l.id=league_id and l.owner_id=auth.uid()));
create policy "owner settings" on public.league_settings for all to authenticated using(exists(select 1 from public.seasons s join public.leagues l on l.id=s.league_id join public.draft_allowed_users a on a.user_id=auth.uid() where s.id=season_id and l.owner_id=auth.uid())) with check(exists(select 1 from public.seasons s join public.leagues l on l.id=s.league_id join public.draft_allowed_users a on a.user_id=auth.uid() where s.id=season_id and l.owner_id=auth.uid()));
create policy "owner managers" on public.managers for all to authenticated using(exists(select 1 from public.leagues l join public.draft_allowed_users a on a.user_id=auth.uid() where l.id=league_id and l.owner_id=auth.uid())) with check(exists(select 1 from public.leagues l join public.draft_allowed_users a on a.user_id=auth.uid() where l.id=league_id and l.owner_id=auth.uid()));
create policy "owner teams" on public.season_teams for all to authenticated using(exists(select 1 from public.seasons s join public.leagues l on l.id=s.league_id join public.draft_allowed_users a on a.user_id=auth.uid() where s.id=season_id and l.owner_id=auth.uid())) with check(exists(select 1 from public.seasons s join public.leagues l on l.id=s.league_id join public.draft_allowed_users a on a.user_id=auth.uid() where s.id=season_id and l.owner_id=auth.uid()));
